-- ============================================================================
-- witw 더미 데이터 (now() 상대값)
--
-- 용도: 로컬 개발·기능 확인용 소량 시드 (기사 50건).
--       성능 측정에는 쓰지 마십시오 — 50건에서는 플래너가 항상 seq scan 을
--       고르므로 인덱스 판단이 불가능합니다. scripts/perf/generate-bulk.sql 을
--       사용하십시오.
--
-- 실행: psql -h localhost -U postgres -d witw -f scripts/seed/seed-dev.sql
--
-- 모든 타임스탬프를 실행 시점(anchor) 기준 상대값으로 적재합니다.
-- 언제 돌려도 최신 기사가 "방금 전"이 되므로, CURRENT_TIMESTAMP - INTERVAL '24 hours'
-- 윈도우를 쓰는 쿼리들이 항상 데이터를 잡습니다.
--
-- anchor        = date_trunc('minute', 현재 시각 KST)
-- 원본 기준시각 = 2026-09-04 09:30:00 (이 값 기준의 상대 구조를 그대로 보존)
--
-- 아래 INSERT의 절대 리터럴은 "읽기 좋은 템플릿"이고, 적재 직후 delta만큼
-- 일괄 이동시킵니다. 데이터 간 시간 간격은 원본과 100% 동일합니다.
--
-- 결과 분포 (anchor 기준):
--   article 50건이 anchor-47h10m ~ anchor-20m 구간에 분포
--   그중 24건이 최근 24시간 윈도우에 포함 (US 5 / KR 5 / JP 5 / DE 5 / GB 4)
--
-- 주의: 재실행 가능하도록 맨 앞에서 대상 테이블을 TRUNCATE 합니다.
--       flyway_schema_history 는 건드리지 않습니다.
-- ============================================================================

BEGIN;

TRUNCATE article_country_mention, country_tone, article_summary,
         article, issue, theme, field, country;

CREATE TEMP TABLE _anchor ON COMMIT DROP AS
SELECT
    date_trunc('minute', CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul') AS at,
    date_trunc('minute', CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')
        - TIMESTAMP '2026-09-04 09:30:00' AS delta;


-- ----------------------------------------------------------------------------
-- 절대 리터럴 -> anchor 상대값으로 일괄 이동
-- (deleted_at 은 NULL 이므로 NULL + interval = NULL 로 그대로 유지됨)
-- ----------------------------------------------------------------------------

UPDATE field
SET created_at = created_at + (SELECT delta FROM _anchor);

UPDATE theme
SET created_at = created_at + (SELECT delta FROM _anchor),
    updated_at = updated_at + (SELECT delta FROM _anchor);

UPDATE issue
SET first_seen_at = first_seen_at + (SELECT delta FROM _anchor),
    created_at    = created_at    + (SELECT delta FROM _anchor),
    updated_at    = updated_at    + (SELECT delta FROM _anchor);

UPDATE article
SET crawled_at        = crawled_at        + (SELECT delta FROM _anchor),
    created_at        = created_at        + (SELECT delta FROM _anchor),
    published_at      = published_at      + (SELECT delta FROM _anchor),
    issue_assigned_at = issue_assigned_at + (SELECT delta FROM _anchor),
    deleted_at        = deleted_at        + (SELECT delta FROM _anchor);

-- ----------------------------------------------------------------------------
-- 파생 테이블: 이동이 끝난 article 에서 anchor 기준으로 계산
-- ----------------------------------------------------------------------------

-- 이슈별 국가 반응 온도: anchor 기준 최근 24시간 기사로 계산
SELECT
    (SELECT at FROM _anchor) AS calculated_at,
    issue_id,
    publisher_country_code AS country_code,
    ROUND(AVG(tone_score), 2) AS tone_avg,
    ROUND(COALESCE(STDDEV_POP(tone_score), 0), 2) AS tone_sd,
    COUNT(*) AS article_count
FROM article
WHERE published_at >= (SELECT at FROM _anchor) - INTERVAL '24 hours'
  AND published_at <= (SELECT at FROM _anchor)
  AND issue_id IS NOT NULL
  AND deleted_at IS NULL
GROUP BY issue_id, publisher_country_code;

-- 전체/오늘 기사 수 스냅샷 (오늘 = anchor 가 속한 날의 00:00 ~ anchor)
SELECT
    1,
    COUNT(*),
    COUNT(*) FILTER (WHERE crawled_at >= date_trunc('day', (SELECT at FROM _anchor))
                       AND crawled_at <= (SELECT at FROM _anchor)),
    (SELECT at FROM _anchor)
FROM article
WHERE deleted_at IS NULL;


SELECT setval(pg_get_serial_sequence('field', 'id'), COALESCE((SELECT MAX(id) FROM field), 1), true);
SELECT setval(pg_get_serial_sequence('theme', 'id'), COALESCE((SELECT MAX(id) FROM theme), 1), true);
SELECT setval(pg_get_serial_sequence('issue', 'id'), COALESCE((SELECT MAX(id) FROM issue), 1), true);
SELECT setval(pg_get_serial_sequence('article_summary', 'id'), COALESCE((SELECT MAX(id) FROM article_summary), 1), true);

COMMIT;

ANALYZE field;
ANALYZE country;
ANALYZE theme;
ANALYZE issue;
ANALYZE article;
ANALYZE article_country_mention;
ANALYZE country_tone;
ANALYZE article_summary;
